def fill_at_next_open(orders, bars):
    o = np.asarray(orders)[:-1]
    t = np.flatnonzero(o != 0) + 1
    return pd.Series(bars["open"].to_numpy()[t], index=bars.index[t])

def backtest(bars, targets, cash0=1_000_000, costs=None):
    targets = pd.Series(np.asarray(targets), index=bars.index)
    orders = orders_from_targets(targets)
    fills = fill_at_next_open(orders, bars)
    pf = Portfolio(cash0)
    rows = []
    for t, (date, close) in enumerate(bars["close"].items()):
        if date in fills.index:
            qty = int(orders.iloc[t - 1])
            price = fills[date]
            cost = 0.0 if costs is None else costs(qty, price)
            pf.fill(qty, price, cost)
        rows.append((pf.shares, pf.cash, pf.equity(close)))
    return pd.DataFrame(rows, columns=["shares", "cash", "equity"], index=bars.index)

def trade_cost(qty, price, per_share=0.005, minimum=1.0, half_spread_bp=2.0):
    if qty == 0:
        return 0.0
    q = abs(qty)
    return max(per_share * q, minimum) + q * price * half_spread_bp / 10_000

def _run(bars, targets, costs=None):
    out = backtest(bars, targets, costs=costs)
    out.insert(0, "target", np.asarray(targets))
    return out

def honest_engine(bars):
    return _run(bars, target_positions(momentum_signal(bars["close"], 1), 10_000))

def honest_engine_with_costs(bars):
    return _run(bars, target_positions(momentum_signal(bars["close"], 1), 10_000), costs=trade_cost)

def peek_engine(bars):
    close = bars["close"]
    signal = np.sign(close.shift(-1) / close - 1).fillna(0.0)
    return _run(bars, target_positions(signal, 10_000))

def peek_engine_with_costs(bars):
    close = bars["close"]
    signal = np.sign(close.shift(-1) / close - 1).fillna(0.0)
    return _run(bars, target_positions(signal, 10_000), costs=trade_cost)

def scaled_engine(bars):
    close = bars["close"]
    vol = close.pct_change().std()
    signal = momentum_signal(close, 1) * 0.005 / vol
    return _run(bars, target_positions(signal, 10_000))

def scaled_engine_with_costs(bars):
    close = bars["close"]
