def centred_engine(bars):
    close = bars["close"]
    signal = np.sign(close - close.rolling(5, center=True).mean()).fillna(0.0)
    return _run(bars, target_positions(signal, 10_000))

def late_engine(bars):
    # honest for its first 300 rows, then it reads tomorrow's close
    close = bars["close"]
    signal = momentum_signal(close, 1).to_numpy().copy()
    peek = np.sign(close.shift(-1) / close - 1).fillna(0.0).to_numpy()
    signal[300:] = peek[300:]
    return _run(bars, target_positions(pd.Series(signal, index=close.index), 10_000))

def noise_after(bars, cut, seed=0):
    # the same bars, with every price after row cut scaled by seeded noise
    rng = np.random.default_rng(seed)
    out = bars.copy()
    k = np.exp(0.02 * rng.standard_normal(len(bars) - cut))
    for col in ["open", "high", "low", "close"]:
        out[col] = np.r_[bars[col].to_numpy()[:cut], bars[col].to_numpy()[cut:] * k]
    return out

def lookahead_check(run, bars, cut):
    full = run(bars).iloc[:cut]
    part = run(bars.iloc[:cut])
    noisy = run(noise_after(bars, cut)).iloc[:cut]

    def same(a, b):
        return a.shape == b.shape and bool(np.allclose(a.to_numpy(float), b.to_numpy(float), rtol=0, atol=1e-9))

    return same(part, full) and same(noisy, full)
